//! Actual public CPU-EP operators; zero-cache row decode and retained dense controls.
#[path = "../benches/common/mod.rs"]
mod common;
use common::{FloatDType, Tensor};
use onnx_runtime_ep_api::{ExecutionProvider, TensorView};
use onnx_runtime_ep_cpu::{CpuExecutionProvider, CpuMemoryResources, CpuWeightCacheLimits, DerivedWeightMemory};
use onnx_runtime_ep_cpu::kernels::{block_quantized_matmul::{BLOCK_QUANT_MATMUL_DENSE_EXPANSIONS as MM_EXPAND, BLOCK_QUANT_MATMUL_CACHED_DENSE_TEST_HITS as MM_HIT},block_quantized_moe::{BLOCK_QUANT_MOE_DENSE_EXPANSIONS as MOE_EXPAND,BLOCK_QUANT_MOE_CACHED_DENSE_TEST_HITS as MOE_HIT}};
use onnx_runtime_ir::{Attribute,DataType,Node,NodeId,ValueId};
use onnx_runtime_memory_api::Tier;
use onnx_runtime_memory_governor::{HolderId,LeaseLedger,LedgerGovernor,MemoryGovernor};
use std::{hint::black_box,sync::atomic::Ordering,time::Instant};
fn usage()->(f64,u64){let mut u=std::mem::MaybeUninit::<libc::rusage>::uninit();assert_eq!(unsafe{libc::getrusage(libc::RUSAGE_SELF,u.as_mut_ptr())},0);let u=unsafe{u.assume_init()};(u.ru_utime.tv_sec as f64+u.ru_utime.tv_usec as f64/1e6+u.ru_stime.tv_sec as f64+u.ru_stime.tv_usec as f64/1e6,if cfg!(target_os="macos"){u.ru_maxrss as u64}else{u.ru_maxrss as u64*1024})}
fn packed(experts:Option<usize>,output:usize,input:usize)->Tensor{let mut shape=vec![output,input/32,17];if let Some(e)=experts{shape.insert(0,e);}let mut bytes=vec![0u8;shape.iter().product()];let mut state=0x7a63_51d9u32^(output as u32).rotate_left(9)^input as u32;for b in bytes.chunks_exact_mut(17){state=state.wrapping_mul(1664525).wrapping_add(1013904223);b[0]=125+((state>>28)%3)as u8;for v in &mut b[1..]{state=state.wrapping_mul(1664525).wrapping_add(1013904223);*v=(state>>24)as u8;}}Tensor::u8(&shape,&bytes)}
fn main(){
 let args:Vec<_>=std::env::args().skip(1).collect();assert_eq!(args.len(),7,"kind mode rows hidden inter iterations output-file");let kind=&args[0];let mode=&args[1];assert!(matches!(kind.as_str(),"matmul"|"moe"));assert!(matches!(mode.as_str(),"streamed"|"warm"));let number=|i:usize|args[i].parse::<usize>().unwrap();let(m,k,n,reps)=(number(2),number(3),number(4),number(5));assert!(m>0&&k>0&&n>0&&k%32==0&&n%32==0&&reps>0);
 let moe=kind=="moe";let dense_bytes=k*n*4*if moe{2}else{1};let budget=if mode=="warm"{dense_bytes}else{0};let limit=64*1024*1024;
 common::init_decode_topology();let books=LedgerGovernor::new(LeaseLedger::new(0,limit,0));let resources=CpuMemoryResources::new(DerivedWeightMemory::governed(&books,HolderId::new(13)).unwrap(),CpuWeightCacheLimits{dense_bytes:budget,expert_bytes:0}).unwrap();let ep=CpuExecutionProvider::with_resources(resources);
 let mut node=if moe{Node::new(NodeId(0),"BlockQuantizedMoE",vec![Some(ValueId(0)),Some(ValueId(1)),Some(ValueId(2)),None,Some(ValueId(4))],vec![ValueId(5)])}else{Node::new(NodeId(0),"BlockQuantizedMatMul",vec![Some(ValueId(0)),Some(ValueId(1))],vec![ValueId(5)])};node.domain=onnx_runtime_ir::RUNTIME_DOMAIN.into();node.attributes.insert("block_layout_version".into(),Attribute::Int(1));
 if moe{for(name,v)in [("fc1_format",Attribute::String(b"mxfp4".to_vec())),("fc2_format",Attribute::String(b"mxfp4".to_vec())),("activation_type",Attribute::String(b"silu".to_vec())),("k",Attribute::Int(1)),("normalize_routing_weights",Attribute::Int(1))]{node.attributes.insert(name.into(),v);}}else{node.attributes.insert("K".into(),Attribute::Int(k as i64));node.attributes.insert("N".into(),Attribute::Int(n as i64));node.attributes.insert("format".into(),Attribute::String(b"mxfp4".to_vec()));}
 let mut kernel=ep.get_kernel(&node,&[],1).unwrap();if mode=="warm"{kernel.set_constant_inputs(if moe{&[false,false,true,false,true]}else{&[false,true]});}
 let input=Tensor::floats(FloatDType::F32,&[m,k],&(0..m*k).map(|i|(i%31)as f32/1000.-0.015).collect::<Vec<_>>());let fc1=packed(moe.then_some(2),n,k);let fc2=moe.then(||packed(Some(2),k,n));let logits=moe.then(||Tensor::floats(FloatDType::F32,&[m,2],&(0..m).flat_map(|_|[2.,0.]).collect::<Vec<_>>()));let mut output=Tensor::zeros(FloatDType::F32,&[m,if moe{k}else{n}]);
 let inputs=if moe{vec![input.view(),logits.as_ref().unwrap().view(),fc1.view(),TensorView::absent(DataType::Float32),fc2.as_ref().unwrap().view()]}else{vec![input.view(),fc1.view()]};let(expand,hits)=if moe{(&MOE_EXPAND,&MOE_HIT)}else{(&MM_EXPAND,&MM_HIT)};let expansions_per_call=if moe{2}else{1};let initial=expand.load(Ordering::Relaxed);kernel.execute(&inputs,&mut[output.view_mut()]).unwrap();assert_eq!(expand.load(Ordering::Relaxed)-initial,if mode=="warm"{expansions_per_call}else{0});assert_eq!(books.used(Tier::Host),budget as u64);
 let warm_cpu=usage().0;while usage().0-warm_cpu<0.05{kernel.execute(&inputs,&mut[output.view_mut()]).unwrap();}let before=(expand.load(Ordering::Relaxed),hits.load(Ordering::Relaxed));let mut cpu_samples=Vec::new();let mut wall_samples=Vec::new();for _ in 0..9{let start=usage().0;let wall=Instant::now();for _ in 0..reps{kernel.execute(black_box(&inputs),black_box(&mut[output.view_mut()])).unwrap();}cpu_samples.push((usage().0-start)*1000./reps as f64);wall_samples.push(wall.elapsed().as_secs_f64()*1000./reps as f64);}cpu_samples.sort_by(f64::total_cmp);wall_samples.sort_by(f64::total_cmp);let peak=usage().1;assert_eq!(expand.load(Ordering::Relaxed)-before.0,0);assert_eq!(hits.load(Ordering::Relaxed)-before.1,if mode=="warm"{9*reps*expansions_per_call}else{0});assert_eq!(books.used(Tier::Host),budget as u64);
 std::fs::write(&args[6],output.f32s().iter().flat_map(|x|x.to_le_bytes()).collect::<Vec<_>>()).unwrap();let checksum:f64=output.f32s().iter().map(|&x|x as f64).sum();let control=common::make_kernel("Relu",[],&[vec![16384]],24);let values=Tensor::floats(FloatDType::F32,&[16384],&common::float_values(16384));let mut result=Tensor::zeros(FloatDType::F32,&[16384]);for _ in 0..1000{control.execute(&[values.view()],&mut[result.view_mut()]).unwrap();black_box(result.f32s());}let mut controls=Vec::new();for _ in 0..9{let start=usage().0;for _ in 0..30000{control.execute(&[values.view()],&mut[result.view_mut()]).unwrap();black_box(result.f32s());}controls.push((usage().0-start)*1000.);}controls.sort_by(f64::total_cmp);let control_cpu=controls[4];drop(kernel);assert_eq!(books.used(Tier::Host),0);
 println!("kind={kind} mode={mode} rows={m} hidden={k} inter={n} reps={reps} threads={} cpu_ms={} wall_ms={} peak_rss_bytes={peak} dense_bytes={budget} host_limit_bytes={limit} dense_expansions=0 cached_hits={} checksum={checksum:.12} control_cpu_ms={control_cpu}",rayon::current_num_threads(),cpu_samples[4],wall_samples[4],hits.load(Ordering::Relaxed)-before.1);
}
